import PQueue from 'p-queue';

const queue = new PQueue({ concurrency: 8 });      // 8 jobs in flight at most

export function submit(job: Job): void {
  queue.add(() => process(job));                     // buffered, settles on completion
}

setInterval(() => metrics.gauge('backlog', queue.size + queue.pending), 5000);

