import { Queue, Worker } from 'bullmq';

interface JobData { orderId: string; payload: unknown }

const jobs = new Queue<JobData>('orders', { connection });
await jobs.add('process', { orderId, payload }, { attempts: 5, backoff: { type: 'exponential', delay: 500 } });

new Worker<JobData>('orders', async job => process(job.data),
                   { connection, concurrency: 8 });
